import{_ as o}from"./chunks/files.B17OUyrr.js";import{_ as t,c as a,o as s,a2 as i}from"./chunks/framework.CIiVzG-O.js";const f=JSON.parse('{"title":"Compare files","description":"Open two files side by side, read colour-coded changes, jump between them and edit or share.","frontmatter":{"title":"Compare files","description":"Open two files side by side, read colour-coded changes, jump between them and edit or share."},"headers":[],"relativePath":"guide/files.md","filePath":"guide/files.md","lastUpdated":1793948370000}'),r={name:"guide/files.md"};function n(l,e,h,d,c,p){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="compare-files" tabindex="-1">Compare files <a class="header-anchor" href="#compare-files" aria-label="Permalink to &quot;Compare files&quot;">​</a></h1><p>This is the view most people start with: two versions of the same file, next to each other, with every difference marked.</p><img src="'+o+'" alt="Two text files side by side with coloured changes" class="guide-shot"><h2 id="open-two-files" tabindex="-1">Open two files <a class="header-anchor" href="#open-two-files" aria-label="Permalink to &quot;Open two files&quot;">​</a></h2><p>Use <strong>File → Open</strong>, or simply drag two files onto the qDiff window. Need to reconcile three versions? Add a third pane — the same colour rules apply. Recent comparisons are kept on the welcome screen for next time.</p><h2 id="what-the-colours-mean" tabindex="-1">What the colours mean <a class="header-anchor" href="#what-the-colours-mean" aria-label="Permalink to &quot;What the colours mean&quot;">​</a></h2><ul><li><strong>Soft red</strong> — content on this side was removed or belongs to the older version.</li><li><strong>Soft green</strong> — content was added or belongs to the newer version.</li><li><strong>Deeper colour inside a line</strong> — exactly which words changed. A single changed word never disappears inside a whole coloured line.</li></ul><p>Both sides scroll together, so the two versions always stay on the same line.</p><h2 id="move-between-changes" tabindex="-1">Move between changes <a class="header-anchor" href="#move-between-changes" aria-label="Permalink to &quot;Move between changes&quot;">​</a></h2><p>Click the slim map beside the text to jump anywhere in the file, or use the previous / next buttons (they have keyboard shortcuts too) to walk through changes one by one. The map also shows where you are in a long document.</p><h2 id="fix-things-as-you-go" tabindex="-1">Fix things as you go <a class="header-anchor" href="#fix-things-as-you-go" aria-label="Permalink to &quot;Fix things as you go&quot;">​</a></h2><p>Either side can be edited and undone. For each change you can copy it across, replace it or delete it — straight from the comparison, without opening another editor. When you are done, save as usual.</p><div class="tip custom-block"><p class="custom-block-title">Share a picture</p><p>Select a change and export it as an image: a clean two-column picture that is easy to paste into a message or a review. The exported picture is free of any marking.</p></div><p>Next: <a href="./folders.html">compare whole folders</a>.</p>',14)])])}const g=t(r,[["render",n]]);export{f as __pageData,g as default};
